import{_ as a,c as n,o as s,aj as t}from"./chunks/framework.Id7s26SP.js";const p=JSON.parse('{"title":"Interface: ChannelSubscribeFailedEvent","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/ChannelSubscribeFailedEvent.md","filePath":"reference/js-bao-wss-client/api/interfaces/ChannelSubscribeFailedEvent.md"}'),r={name:"reference/js-bao-wss-client/api/interfaces/ChannelSubscribeFailedEvent.md"};function i(c,e,o,l,h,d){return s(),n("div",null,[...e[0]||(e[0]=[t('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / ChannelSubscribeFailedEvent</p><h1 id="interface-channelsubscribefailedevent" tabindex="-1">Interface: ChannelSubscribeFailedEvent <a class="header-anchor" href="#interface-channelsubscribefailedevent" aria-label="Permalink to “Interface: ChannelSubscribeFailedEvent”">​</a></h1><p>A channel subscription the server refused when nothing was waiting on it.</p><p>Emitted over the <code>channelSubscribeFailed</code> event channel (<code>client.on(&quot;channelSubscribeFailed&quot;, ...)</code>). The case this exists for is RECONNECT: after the socket comes back the client presents each held grant again, and a grant that expired while the connection was down is refused with no pending call to reject. The registration for that channel — and only that channel — is dropped, and this is how an app hears about it, so it can ask its authorizing function for a fresh grant and subscribe again.</p><p>A refusal that answers a <a href="./../classes/JsBaoClient.html#subscribetochannel">JsBaoClient.subscribeToChannel</a> call is reported by rejecting that promise instead, so a failure is never announced twice. <code>message</code> is the server&#39;s uniform refusal: an expired, tampered, cross-app or cross-user grant are deliberately indistinguishable.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="channel" tabindex="-1">channel <a class="header-anchor" href="#channel" aria-label="Permalink to “channel”">​</a></h3><blockquote><p><strong>channel</strong>: <code>string</code></p></blockquote><hr><h3 id="message" tabindex="-1">message <a class="header-anchor" href="#message" aria-label="Permalink to “message”">​</a></h3><blockquote><p><strong>message</strong>: <code>string</code></p></blockquote>',13)])])}const f=a(r,[["render",i]]);export{p as __pageData,f as default};
